fn update(scene: &mut GameScene<'_>, time: &FrameTime) {
    let target =
        scene.counter_or("turns", 0) as f32 * std::f32::consts::FRAC_PI_2;
    let [x, y, z] = scene.object("Cube").rotation();
    if y < target {
        let y = (y + std::f32::consts::TAU * time.delta_seconds()).min(target);
        scene.object("Cube").set_rotation([x, y, z]);
    } else if scene.pressed("turn") {
        scene.add_to_counter("turns", 1);
    }
}
